SEED_CPP = '#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> minx(n), miny(n);\n    int max_width = 0;\n    int cur_y = 0;\n    vector<int> heights(n);\n    for (int i = 0; i < n; ++i) {\n        int k; cin >> k;\n        int mnx=INT_MAX, mxx=INT_MIN, mny=INT_MAX, mxy=INT_MIN;\n        for (int j = 0; j < k; ++j) {\n            int x, y; cin >> x >> y;\n            mnx=min(mnx,x); mxx=max(mxx,x);\n            mny=min(mny,y); mxy=max(mxy,y);\n        }\n        minx[i]=mnx; miny[i]=mny;\n        int w=mxx-mnx+1, h=mxy-mny+1;\n        heights[i]=h;\n        max_width=max(max_width,w);\n        cur_y+=h;\n    }\n    cout << max_width << " " << cur_y << endl;\n    int y=0;\n    for (int i = 0; i < n; ++i) {\n        cout << -minx[i] << " " << y-miny[i] << " 0 0" << endl;\n        y+=heights[i];\n    }\n    return 0;\n}'
